/** Project-only installation. Host capabilities and private runtime state stay on the broker. */
export const getExecutorProjectToolInstallSchema = defineSchema((v) => v.object({
    ...artifactShape(v),
    mode: v.literal("project-tools"),
    binding: getExecutorBindingSchema(),
    context: v.object({
        agentId: getExecutorDiscoveryIdSchema(),
        projectId: getExecutorDiscoveryIdSchema().nullable(),
        runId: getExecutorDiscoveryIdSchema(),
        userId: getExecutorDiscoveryIdSchema().optional(),
        projectSlug: getExecutorDiscoveryIdSchema().optional(),
        branch: getExecutorDiscoveryIdSchema().nullable().optional(),
    }).strict(),
    allowedToolNames: v.array(getExecutorToolIdSchema()).max(EXECUTOR_TOOL_LIMITS.maxToolsPerSource),
    maxCalls: v.number().int().min(1).max(4096),
    maxConcurrent: v.number().int().min(1).max(32),
    limits: getExecutorToolLimitsSchema().optional(),
}).strict().refine((input) => new Set(input.allowedToolNames).size === input.allowedToolNames.length &&
    (input.context.projectId !== null ||
        (input.owner.scopeKind === "global" && input.context.projectSlug === undefined &&
            input.context.branch == null)), "Invalid project tool grant or source context"));
/** Snapshot before parsing so installation never retains a caller's mutable objects. */
export function parseExecutorInstallation(schema, input) {
    const snapshot = snapshotBoundedJsonValue(input);
    if (!snapshot.success ||
        new TextEncoder().encode(JSON.stringify(snapshot.value)).byteLength > 64 * 1024) {
        throw new TypeError("Invalid executor installation");
    }
    const result = schema.safeParse(snapshot.value);
    if (!result.success)
        throw new TypeError("Invalid executor installation");
    return result.data;
}
